import{_ as a,o as t,c as e,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"05-1 第一个完整项目：用 Escrow 理解链上托管","description":"","frontmatter":{},"headers":[],"relativePath":"05-project/index.md","filePath":"05-project/index.md","lastUpdated":1791601077000}'),i={name:"05-project/index.md"};function l(d,s,p,r,o,c){return t(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="_05-1-第一个完整项目-用-escrow-理解链上托管" tabindex="-1">05-1 第一个完整项目：用 Escrow 理解链上托管 <a class="header-anchor" href="#_05-1-第一个完整项目-用-escrow-理解链上托管" aria-label="Permalink to &quot;05-1 第一个完整项目：用 Escrow 理解链上托管&quot;">​</a></h1><blockquote><p><strong>本课目标</strong>：先用业务语言画出一笔订单的规则、参与者、状态和失败情况，再读 Solidity 代码。不要上来就复制 100 行合约。</p><p><strong>学习环境</strong>：仅限本地 Foundry/Remix VM 或无价值的测试网。教程合约不支持商业仲裁，未经审计，严禁用于真实资金托管。</p></blockquote><h2 id="一句话解释-escrow" tabindex="-1">一句话解释 Escrow <a class="header-anchor" href="#一句话解释-escrow" aria-label="Permalink to &quot;一句话解释 Escrow&quot;">​</a></h2><p>Escrow 意思是<strong>托管</strong>。你想买一件二手商品，但不愿意直接把钱给卖家，于是将钱先放到一个按公开规则执行的托管合约里。</p><p>假设买家 A 与卖家 B 约定：</p><ol><li>A 创建订单时，向托管合约存入 1 ETH 的<strong>虚拟测试资金</strong>。</li><li>B 完成交付，点击“已交付”。</li><li>A 确认满意后，合约释放资金给 B。</li><li>如果超过截止时间仍没有正常结束，A 可以按教程规则申请退款。</li><li>一笔订单只能释放一次，或退款一次，不能同时发生。</li></ol><p>注意：这里的“交付”只是卖家主动声明，<strong>合约自己不能确认真实快递是否签收</strong>。所以这是教学规则，不是公平的电商仲裁产品。</p><h2 id="第一步-明确角色和动作" tabindex="-1">第一步：明确角色和动作 <a class="header-anchor" href="#第一步-明确角色和动作" aria-label="Permalink to &quot;第一步：明确角色和动作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>可以做什么</th><th>不能做什么</th></tr></thead><tbody><tr><td>买家 Buyer</td><td>部署时付款、已交付后放款、到期退款、读状态</td><td>代替卖家标记交付</td></tr><tr><td>卖家 Seller</td><td>截止前标记已交付、读状态</td><td>擅自从合约拿钱</td></tr><tr><td>陌生人</td><td>读公开状态</td><td>标记交付、放款或退款</td></tr></tbody></table><p>所有人都可能直接向合约发交易，所以这些规则必须由合约执行。钱包地址不是实名身份，业务应用要另行解决身份与争议问题。</p><h2 id="第二步-把状态写清楚" tabindex="-1">第二步：把状态写清楚 <a class="header-anchor" href="#第二步-把状态写清楚" aria-label="Permalink to &quot;第二步：把状态写清楚&quot;">​</a></h2><p>本仓库使用四种状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>中文含义</th><th>还可以做什么</th></tr></thead><tbody><tr><td><code>Funded</code></td><td>买家已经付款，钱在合约里</td><td>卖家可在截止前交付，买家可到期退款</td></tr><tr><td><code>Delivered</code></td><td>卖家已声明交付</td><td>买家可以放款，或按规则到期退款</td></tr><tr><td><code>Released</code></td><td>已向卖家释放</td><td>最终状态，不能再放款或退款</td></tr><tr><td><code>Refunded</code></td><td>已向买家退款</td><td>最终状态，不能再放款或退款</td></tr></tbody></table><p>用图表示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>买家创建订单并付测试 ETH</span></span>
<span class="line"><span>             │</span></span>
<span class="line"><span>             ▼</span></span>
<span class="line"><span>          Funded</span></span>
<span class="line"><span>          /    \\</span></span>
<span class="line"><span>   卖家交付     截止后买家退款</span></span>
<span class="line"><span>        /        \\</span></span>
<span class="line"><span>       ▼          ▼</span></span>
<span class="line"><span>   Delivered    Refunded（结束）</span></span>
<span class="line"><span>      /  \\</span></span>
<span class="line"><span>买家放款   截止后买家退款</span></span>
<span class="line"><span>    ▼           ▼</span></span>
<span class="line"><span> Released     Refunded</span></span>
<span class="line"><span> （结束）       （结束）</span></span></code></pre></div><p>这里重要的不是英文单词，而是：<strong>哪些箭头可以走、谁能走、在什么时间能走</strong>。不允许的箭头都应失败。</p><h2 id="第三步-哪些输入部署时必须确定" tabindex="-1">第三步：哪些输入部署时必须确定？ <a class="header-anchor" href="#第三步-哪些输入部署时必须确定" aria-label="Permalink to &quot;第三步：哪些输入部署时必须确定？&quot;">​</a></h2><p>合约部署时传入：</p><ul><li><code>seller</code>：卖家地址。</li><li><code>deadline</code>：一个未来的 Unix 时间戳（秒）。</li><li><code>msg.value</code>：部署交易附带的虚拟 ETH。</li><li><code>msg.sender</code>：自动作为买家地址。</li></ul><p>合约还会记录当前状态为 Funded，并发出 Funded 事件。</p><p>注意：教程是一笔订单部署一个 Escrow 实例。不是使用同一份合约就自动管理全平台成千上万笔订单。这样设计是为了把角色和状态讲清楚。</p><h2 id="第四步-先猜失败场景" tabindex="-1">第四步：先猜失败场景 <a class="header-anchor" href="#第四步-先猜失败场景" aria-label="Permalink to &quot;第四步：先猜失败场景&quot;">​</a></h2><p>正常流程很短，但一个合约真正需要验证的，是下面的问题：</p><ul><li>卖家未交付，买家能否直接放款？<strong>不能。</strong></li><li>陌生人能否标记交付？<strong>不能。</strong></li><li>买家能否在截止前退款？<strong>不能。</strong></li><li>放款之后，买家能否再次退款？<strong>不能。</strong></li><li>收款地址拒绝接收 ETH，资金会不会“凭空消失”？<strong>不应该；交易会回滚，但业务可能卡住。</strong></li><li>买家明明已经收到了货，到期却退款怎么办？<strong>教程没有解决商业争议，这属于真实产品缺失的规则。</strong></li></ul><p>这张清单稍后会变成 Foundry 自动化测试。</p><h2 id="第五步-打开配套项目" tabindex="-1">第五步：打开配套项目 <a class="header-anchor" href="#第五步-打开配套项目" aria-label="Permalink to &quot;第五步：打开配套项目&quot;">​</a></h2><p>本仓库的代码在：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>examples/foundry/</span></span>
<span class="line"><span>├── src/Escrow.sol        # 合约源码</span></span>
<span class="line"><span>└── test/Escrow.t.sol     # 模拟买家、卖家、陌生人的测试</span></span></code></pre></div><p>先运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/foundry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match-contract</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EscrowTest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vv</span></span></code></pre></div><p>注意：<strong>通过测试并不代表已通过专业安全审计，也不等于允许用真钱上线。</strong> 这里只用于检查课程明确列出的规则。</p><h2 id="本课思考题" tabindex="-1">本课思考题 <a class="header-anchor" href="#本课思考题" aria-label="Permalink to &quot;本课思考题&quot;">​</a></h2><p><strong>问题：</strong> 为什么不能只保存一个 <code>isPaid = true/false</code>，而要区分 Funded、Delivered、Released、Refunded？</p><details><summary>参考答案</summary><p>因为“已经付款”并不足以描述后续行为：卖家是否声明交付、资金是否已释放、是否已退款，都影响下一步谁能操作。只有一个布尔值容易让状态组合含糊，导致权限和重复结算问题。</p></details><p><strong>本课验收</strong>：能不用看代码，向别人描述四个状态、三种角色、两条最终路径和至少三种必须失败的操作。</p><p>下一课：<a href="/05-project/escrow">Escrow.sol 全部源码和逐步拆解</a>。</p>`,36)])])}const u=a(i,[["render",l]]);export{g as __pageData,u as default};
